search_script.example_code:
// 1. előszűrés normál kereséssel
const kandidatNotes = api.searchForNotes("#journal"); 

// 2. egyéni keresési feltételek alkalmazása
const matchedNotes = kandidatNotes
    .filter(note => note.title.match(/[0-9]{1,2}\. ?[0-9]{1,2}\. ?[0-9]{4}/));

return matchedNotes;

